    _snv_csv=$(IFS=,; echo "${_snv_caller_codes[*]}")
    export _DY_AUTO_SNV_CALLERS="$_snv_csv"
    colr "...AUTO-CONFIG: snv_callers=${_snv_csv} (from target rules → env)" "$DY_IT1" "$DY_IB1" "$DY_IS1" 1>&2
